90	// EnsureSetup ensures the strategy is properly set up.
91	func EnsureSetup(ctx context.Context) error {
92		if err := EnsureEntireGitignore(ctx); err != nil {
93			return err
94		}
95	
96		// Ensure the entire/checkpoints/v1 orphan branch exists for permanent session storage
97		repo, err := OpenRepository(ctx)
98		if err != nil {
99			return fmt.Errorf("failed to open git repository: %w", err)
100		}
101		defer repo.Close()
102		if err := vercelconfig.InitSettings(ctx); err != nil {
103			return fmt.Errorf("failed to initialize vercel settings: %w", err)
104		}
105		if err := EnsurePrimaryRef(ctx, repo); err != nil {
106			return fmt.Errorf("failed to ensure primary metadata ref: %w", err)
107		}
108	
109		// Install generic hooks (they delegate to strategy at runtime)
110		if !IsGitHookInstalled(ctx) {
111			localDev, absoluteHookPath := hookSettingsFromConfig(ctx)
112			if _, err := InstallGitHook(ctx, true, localDev, absoluteHookPath); err != nil {
113				return fmt.Errorf("failed to install git hooks: %w", err)
114			}
115		}
116		return nil
117	}
118	
119	// FetchTmpRefPrefix is the namespace for temporary refs used by fetch helpers
120	// to land a fetched hash before safely promoting it to a final ref (via
121	// PromoteTmpRefSafely). Prefer using the named constants below when possible.
122	const FetchTmpRefPrefix = "refs/entire-fetch-tmp/"
123	
124	// PromoteTmpRefSafely reads tmpRefName (the ref a fetch just landed into),
125	// advances destRefName to its hash via SafelyAdvanceLocalRef, then removes
126	// the tmp ref. The cleanup is deferred so the tmp ref is reaped even when
127	// the advance fails.
128	//
129	// label is a short human-readable name used in error messages. Typical use:
130	//
131	//	// fetch with refspec "+<src>:<tmpRefName>"
132	//	refs := checkpoint.ResolveRefs(ctx)
133	//	return PromoteTmpRefSafely(ctx, tmpRefName, refs.Primary, refs.Primary.Short())
134	func PromoteTmpRefSafely(ctx context.Context, tmpRefName, destRefName plumbing.ReferenceName, label string) error {
135		repo, err := OpenRepository(ctx)
136		if err != nil {
137			return fmt.Errorf("failed to open repository for %s promote: %w", label, err)
